replays.action('csv', async (ctx) => {
  const quote = (v) => '"' + String(v).replaceAll('"', '""') + '"';
  const rows = [['at_ms', 'method', 'status', 'url', 'duration_ms']].concat(
    ctx.replay.network.map((r) => [r.at, r.method, r.status, r.url, r.duration]),
  );
  await ctx.download(ctx.replay.meta.id + '-network.csv', 'text/csv', rows.map((r) => r.map(quote).join(',')).join('\n'));
});
